import sys

def find_median(k, s, t):
    # Calculate the position of the median string
    total_count = (ord(t[0]) - ord(s[0])) * 26 ** (k - 1) + sum((26 ** i) * (ord(t[i]) - ord('a')) for i in range(1, k)) + 1
    median_position = (total_count // 2) + 1

    # Function to convert a number to its corresponding string
    def num_to_string(num):
        result = []
        for _ in range(k):
            num, remainder = divmod(num, 26)
            if remainder == 0:
                result.append('z')
                num -= 1
            else:
                result.append(chr(ord('a') + remainder - 1))
        return ''.join(reversed(result))

    # Find the median string
    current_num = 0
    for i in range(k):
        for char in 'abcdefghijklmnopqrstuvwxyz':
            next_num = current_num * 26 + (ord(char) - ord('a'))
            if next_num > median_position:
                break
            current_num = next_num
        if current_num == median_position:
            break

    # Adjust the last character if necessary
    if current_num < median_position:
        current_num += 1

    return num_to_string(current_num)

