def find_median_string(k, s, t):
    def get_midpoint(a, b):
        return chr((ord(b) - ord(a)) // 2 + ord(a))

    if k == 1:
        return get_midpoint(s, t)

    midpoint = ''.join(get_midpoint(s[i], t[i]) for i in range(k))
    return midpoint

